+    let handler: (event: any) => void;
+    const subscribe = jest.fn((callback: typeof handler) => {
+        handler = callback;
+        return unsubscribe;
+    });
+
+    beforeEach(() => {
+        jest.useFakeTimers();
+        jest.clearAllMocks();
+        call.mockResolvedValue(undefined);
+        jest.mocked(useEventManager).mockReturnValue({ call, subscribe } as any);
+    });
+
+    afterEach(() => jest.useRealTimers());
+
+    it('calls at five second intervals and stops after five attempts', async () => {
+        const { result } = renderHook(() => usePollEvents());
+        const done = result.current();
+
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await act(async () => {
+                await jest.advanceTimersByTimeAsync(interval - 1);
+            });
+            expect(call).toHaveBeenCalledTimes(step - 1);
+            await act(async () => {
+                await jest.advanceTimersByTimeAsync(1);
+            });
+            expect(call).toHaveBeenCalledTimes(step);
+        }
+
+        await done;
+        await act(async () => {
+            await jest.advanceTimersByTimeAsync(interval * 2);
+        });
